// Decide who gets which email today. Templates, not free generation — a chase email must never invent a deadline.
const cfg = $('Config').first().json;
const today = cfg.today_override ? new Date(cfg.today_override + 'T12:00:00') : new Date();
const iso = d => d.toISOString().slice(0, 10);
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const MONTHS = {
  en: ['January','February','March','April','May','June','July','August','September','October','November','December'],
  lt: ['sausio','vasario','kovo','balandžio','gegužės','birželio','liepos','rugpjūčio','rugsėjo','spalio','lapkričio','gruodžio']
};
const prev = new Date(today.getFullYear(), today.getMonth() + Number(cfg.period_month_offset || 0), 1);  // which month's books are being closed
const month = { en: MONTHS.en[prev.getMonth()], lt: MONTHS.lt[prev.getMonth()] };

const T = {
  en: {
    request: v => ({
      subject: `Documents for ${v.month} bookkeeping — ${v.client}`,
      body: `Hi ${v.first},\n\nTo close your ${v.month} books we still need: ${v.list}.\n\nYou can upload them here: ${v.link} — takes two minutes. Anything unclear, just reply to this email.\n\nThanks!\n${v.firm}` }),
    reminder_1: v => ({
      subject: `Gentle reminder: ${v.month} documents — ${v.client}`,
      body: `Hi ${v.first},\n\nA quick nudge — we're still missing: ${v.list}.\n\nUpload here whenever you have a moment: ${v.link}\n\nThanks!\n${v.firm}` }),
    reminder_2: v => ({
      subject: `Deadline ${v.deadline}: ${v.month} documents — ${v.client}`,
      body: `Hi ${v.first},\n\nWe need the following by ${v.deadline} to file your ${v.month} reports on time: ${v.list}.\n\nUpload here: ${v.link}\n\nIf something is delayed, reply and let us know — we'll work around it.\n\n${v.firm}` }),
  },
  lt: {
    request: v => ({
      subject: `Dokumentai ${v.month} mėn. apskaitai — ${v.client}`,
      body: `Sveiki, ${v.first},\n\nkad užbaigtume ${v.month} mėn. apskaitą, dar trūksta: ${v.list}.\n\nĮkelti galite čia: ${v.link} — užtruks porą minučių. Jei kiltų klausimų, tiesiog atsakykite į šį laišką.\n\nAčiū!\n${v.firm}` }),
    reminder_1: v => ({
      subject: `Priminimas: ${v.month} mėn. dokumentai — ${v.client}`,
      body: `Sveiki, ${v.first},\n\ntrumpas priminimas — vis dar trūksta: ${v.list}.\n\nĮkelkite, kai turėsite minutę: ${v.link}\n\nAčiū!\n${v.firm}` }),
    reminder_2: v => ({
      subject: `Terminas ${v.deadline}: ${v.month} mėn. dokumentai — ${v.client}`,
      body: `Sveiki, ${v.first},\n\nkad laiku pateiktume ${v.month} mėn. ataskaitas, iki ${v.deadline} mums reikia: ${v.list}.\n\nĮkelti galite čia: ${v.link}\n\nJei kažkas vėluoja — atsakykite ir susitarsime.\n\n${v.firm}` }),
  }
};

const ORDER = ['request', 'reminder_1', 'reminder_2', 'escalate'];
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c.client_id) continue;
  const missing = String(c.docs_missing || '').split(';').map(s => s.trim()).filter(Boolean);
  if (String(c.status || '').toLowerCase() === 'complete' || !missing.length) continue;   // rule 1: never email a completed client

  const lang = String(c.language || 'en').toLowerCase() === 'lt' ? 'lt' : 'en';
  const first = c.first_request_date ? new Date(c.first_request_date + 'T12:00:00') : null;
  const days = first ? Math.floor((today - first) / 86400000) : 0;
  let stage = !first ? 'request' : days >= 12 ? 'escalate' : days >= 8 ? 'reminder_2' : days >= 4 ? 'reminder_1' : 'request';
  const last = String(c.last_stage || '');
  if (last && ORDER.indexOf(stage) <= ORDER.indexOf(last)) continue;                    // rule 2: never send the same stage twice
  const sent = Number(c.client_emails_sent || 0);
  if (stage !== 'escalate' && sent >= Number(cfg.max_client_emails || 3)) stage = 'escalate'; // rule 3: hard cap on client-facing emails

  const vars = { first: c.contact_first_name, client: c.client_name, month: month[lang], list: missing.join(', '),
                 link: cfg.upload_form_url, firm: cfg.firm_name, deadline: iso(addDays(today, 3)), days };
  let to, subject, body;
  if (stage === 'escalate') {
    to = cfg.accountant_email;
    subject = `[Action needed] ${c.client_name} — ${days} days without documents`;
    body = [
      `Client: ${c.client_name} — ${c.contact_first_name}, ${c.email}`,
      `Missing: ${missing.join(', ')}`,
      `First request: ${c.first_request_date}   Last email: ${c.last_sent_date} (${last})`,
      `Client emails sent: ${sent} — automated chasing stopped.`,
      '',
      'Next step: a phone call. The row stays open until documents arrive via the upload link:',
      cfg.upload_form_url
    ].join('\n');
  } else {
    to = c.email;
    ({ subject, body } = T[lang][stage](vars));
  }
  const redirect = (cfg.demo_redirect_to || '').trim();
  const redirected = redirect && redirect !== to;
  out.push({ json: {
    client_id: c.client_id, client_name: c.client_name, stage, days_since_request: days, language: lang,
    recipient_original: to,
    to: redirected ? redirect : to,
    subject: redirected ? `[DEMO → ${to}] ${subject}` : subject,
    body,
    first_request_date: c.first_request_date || iso(today),
    last_sent_date: iso(today),
    last_stage: stage,
    client_emails_sent: stage === 'escalate' ? sent : sent + 1,
    docs_missing: missing.join('; '),
    timestamp: new Date().toISOString()
  }});
}
return out;

// A client uploaded something: shrink docs_missing, close the row when nothing is left, thank them.
const cfg = $('Config').first().json;
const f = $('TriggerClientUpload').first().json;
const bin = $('TriggerClientUpload').first().binary || {};
const rows = $input.all().map(i => i.json);
const id = String(f['Client ID'] || '').trim().toUpperCase();
const c = rows.find(r => String(r.client_id || '').toUpperCase() === id);
if (!c) throw new Error(`Unknown client id "${id}" — check the Clients sheet`);

const desc = String(f['Which document is this?'] || '').toLowerCase();
const missing = String(c.docs_missing || '').split(';').map(s => s.trim()).filter(Boolean);
const words = desc.split(/[^a-z0-9ąčęėįšųūž]+/i).filter(w => w.length > 3);
const received = missing.filter(m => words.some(w => m.toLowerCase().includes(w)));
const remaining = missing.filter(m => !received.includes(m));
const status = remaining.length ? 'active' : 'complete';
const lang = String(c.language || 'en').toLowerCase() === 'lt' ? 'lt' : 'en';
const files = Object.values(bin).map(b => b.fileName).join(', ') || '(no file)';

const subject = lang === 'lt' ? `Gavome jūsų dokumentus — ${c.client_name}` : `Documents received — ${c.client_name}`;
const body = lang === 'lt'
  ? `Sveiki, ${c.contact_first_name},\n\ngavome: ${received.length ? received.join(', ') : desc}.\n\n${remaining.length ? 'Dar trūksta: ' + remaining.join(', ') + '.\nĮkelti: ' + cfg.upload_form_url : 'Visi šio mėnesio dokumentai gauti — ačiū, daugiau nieko nereikia.'}\n\n${cfg.firm_name}`
  : `Hi ${c.contact_first_name},\n\nReceived: ${received.length ? received.join(', ') : desc}.\n\n${remaining.length ? 'Still missing: ' + remaining.join(', ') + '.\nUpload: ' + cfg.upload_form_url : "That's everything for this month — thank you, nothing more needed."}\n\n${cfg.firm_name}`;

const redirect = (cfg.demo_redirect_to || '').trim();
return [{ json: {
  client_id: c.client_id, client_name: c.client_name, language: lang,
  received: received.join('; ') || desc, docs_missing: remaining.join('; '), status,
  recipient_original: c.email, to: redirect || c.email,
  subject: redirect ? `[DEMO → ${c.email}] ${subject}` : subject, body,
  files, timestamp: new Date().toISOString()
}}];

// Monday morning: who is still missing what, at which stage, who is escalated.
const cfg = $('Config').first().json;
const today = cfg.today_override ? new Date(cfg.today_override + 'T12:00:00') : new Date();
const rows = $input.all().map(i => i.json).filter(r => r.client_id);
const open = rows.filter(r => String(r.status).toLowerCase() !== 'complete' && String(r.docs_missing || '').trim());
const days = r => r.first_request_date ? Math.floor((today - new Date(r.first_request_date + 'T12:00:00')) / 86400000) : 0;
const pad = (s, n) => String(s ?? '').padEnd(n);
const lines = [
  `Document chase — weekly status (${today.toISOString().slice(0, 10)})`, '',
  `Clients: ${rows.length}   Complete: ${rows.length - open.length}   Still open: ${open.length}`, '',
  pad('Client', 24) + pad('Stage', 12) + pad('Days', 6) + 'Missing',
  '-'.repeat(70),
  ...open.sort((a, b) => days(b) - days(a)).map(r => pad(r.client_name, 24) + pad(r.last_stage || 'not started', 12) + pad(days(r), 6) + r.docs_missing),
  '', 'Escalated (needs a call): ' + (open.filter(r => r.last_stage === 'escalate').map(r => r.client_name).join(', ') || 'none'),
  '', `Upload link for clients: ${cfg.upload_form_url}`
];
return [{ json: { to: cfg.accountant_email, subject: `Weekly document chase — ${open.length} clients still open`, body: lines.join('\n') } }];
